    /// <summary>Phase 27 — route a click on the DS1 in-game (Escape) menu.
    /// RESUME closes it; OPTIONS opens the Options dialog; SAVE/LOAD reuse the
    /// F5/F9 quicksave path (a slot-picker screen lands with multi_inventory);
    /// EXIT quits the window (DS1's show_exit_game_dialog confirm is a later
    /// refinement).</summary>
    private void HandleInGameMenuAction(PauseMenu.Action action)
    {
        switch (action)
        {
            case PauseMenu.Action.Resume:   _pauseMenu.Close(); break;
            case PauseMenu.Action.Options:  _pauseMenu.Close(); OpenOptionsMenu(); break;
            case PauseMenu.Action.SaveGame: _pauseMenu.Close(); OpenSaveDialog(); break;
            case PauseMenu.Action.LoadGame: _pauseMenu.Close(); OpenLoadDialog(mainMenuStyle: false); break;
            case PauseMenu.Action.ExitGame: _window.Close(); break;
        }
    }

    /// <summary>Phase 19c — quicksave to the single profile slot. Shared by the
    /// F5 key and the in-game menu's SAVE GAME button. Silent on a viewer-mode
    /// boot (CaptureSave still writes, but ApplySave refuses it without a region).</summary>
    private void DoQuickSave()
    {
        var path = SiegeFX.Core.Save.SaveStore.QuicksavePath();
        try
        {
            var save = CaptureSave();
            SiegeFX.Core.Save.SaveStore.Save(path, save);
            Console.WriteLine($"  save: wrote {save.Actors.Count} actor(s) + " +
                              $"{save.LootPiles.Count} pile(s) -> {path}");
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"  save: failed -- {ex.Message}");
        }
    }

    /// <summary>Open DS1's Save Game window. Enumerates existing saves for the
    /// list and pre-fills the name box with the day's date (DS1's default),
    /// prefixed with the hero name when one is known.</summary>
    private void OpenSaveDialog()
    {
        var saves = SiegeFX.Core.Save.SaveStore.ListSaves();
        // DS1 pre-fills the name box with "<hero> (<elapsed>)" — e.g.
        // "WOOT (0-13-16)" — so accepting the default gives the timestamped
        // names the Load window shows. Fall back to the day's date when no hero
        // name / clock is available (viewer boot).
        string def = !string.IsNullOrWhiteSpace(_heroName)
            ? $"{_heroName} ({FormatElapsedDashed(_playSeconds)})"
            : DateTime.Now.ToString("MMM d, yyyy");
        _saveDialog.Open(saves, def);
    }

    /// <summary>Open DS1's Load Game window. <paramref name="mainMenuStyle"/>
    /// picks the ornate frontend pose (from the Single Player submenu) vs the
    /// in-game cpbox pose (from the Escape menu). Populates the list from disk;
    /// the dialog auto-highlights the first row.</summary>
    private void OpenLoadDialog(bool mainMenuStyle)
    {
        // Give the frontend pose the chrome's own 800×600→screen projection so
        // the Load window scales/positions in lockstep with the pillars + title
        // at any resolution (see FrontendScene.GetInterfaceMapping).
        _loadDialog.FrontendMap = (vw, vh) =>
        {
            if (_frontendScene is not null
                && _frontendScene.GetInterfaceMapping(vw, vh, out var ox, out var oy, out var sx, out var sy))
                return (true, ox, oy, sx, sy);
            return (false, 0f, 0f, 0f, 0f);
        };
        var slots = SiegeFX.Core.Save.SaveStore.ListSaves();
        Console.WriteLine($"[load] open dialog (frontend={mainMenuStyle}) saves={slots.Count}");
        _loadDialog.Open(slots, mainMenuStyle);
    }

    /// <summary>Raise DS1's "Game loaded successfully" banner (reuses the save-
    /// toast slot).</summary>
    private void ShowLoadedBanner()
    {
        _saveToastText = "Game loaded successfully.";
        _saveToastRemaining = SaveToastDuration;
    }

    /// <summary>Act on the Load Game window's button result. Load resumes the
    /// highlighted save (in-region via <see cref="ApplySave"/>, or by relaunch
    /// into the save's region when it differs / we're at the main menu); Delete
    /// removes the file and refreshes the list; Cancel closes (returning to the
    /// SP submenu in the frontend pose).</summary>
    private void HandleLoadDialogResult(LoadGameDialog.Result r)
    {
        switch (r)
        {
            case LoadGameDialog.Result.Load:
                if (_loadDialog.Selected is { } lslot) PerformLoad(lslot, _loadDialog.MainMenuStyle);
                break;
            case LoadGameDialog.Result.Delete:
                if (_loadDialog.Selected is { } dslot)
                {
                    SiegeFX.Core.Save.SaveStore.Delete(dslot.Path);
                    _loadDialog.Open(SiegeFX.Core.Save.SaveStore.ListSaves(), _loadDialog.MainMenuStyle);
                }
                break;
            case LoadGameDialog.Result.Cancel:
                CloseLoadDialog();
                break;
        }
    }

    /// <summary>Close the Load window; from the frontend pose, play the
    /// reverse chrome transition (window flies up, PREVIOUS/NEXT unwind to
    /// BACK, the title drum flips back to SINGLE PLAYER). The SP submenu
    /// re-activates itself once the state settles (FlushSinglePlayerMenu).</summary>
    private void CloseLoadDialog()
    {
        bool wasMainMenu = _loadDialog.MainMenuStyle;
        _loadDialog.Close();
        if (wasMainMenu && _frontendScene is not null
            && (_frontendScene.State == Hud.FrontendScene.ScreenState.LoadGame
             || _frontendScene.State == Hud.FrontendScene.ScreenState.SinglePlayerToLg))
            _frontendScene.SetState(Hud.FrontendScene.ScreenState.LgToSinglePlayer);
    }

    /// <summary>Resume a save. Same-region in-game loads patch the live scene
    /// directly (the quickload path); a different region — always the case from
    /// the main menu — relaunches into that region and applies the save on
    /// boot.</summary>
    private void PerformLoad(SiegeFX.Core.Save.SaveStore.SaveSlot slot, bool mainMenuStyle)
    {
        bool sameRegion = !mainMenuStyle
            && string.Equals(slot.RegionPath, _regionPath ?? "", StringComparison.OrdinalIgnoreCase)
            && _player is not null;
        if (sameRegion)
        {
            _loadDialog.Close();
            if (_cursorScroll is not null) ClearScrollDrag();
            try
            {
                ApplySave(SiegeFX.Core.Save.SaveStore.Load(slot.Path));
                ShowLoadedBanner();
            }
            catch (Exception ex)
            {
                Console.Error.WriteLine($"  load: failed -- {ex.Message}");
                _saveToastText = "Load failed.";
                _saveToastRemaining = SaveToastDuration;
            }
            return;
        }
        // Cross-region / from the frontend: boot the save's region fresh, then
        // apply. The DS1 resources dir (boot launch) supplies the tanks; a
        // --play-region session reuses its own launch tanks so in-game
        // cross-region loads work there too.
        if (_ds1ResourcesDir is not null)
        {
            _loadDialog.Close();
            LaunchRegionForLoad(_ds1ResourcesDir, slot.Path);
        }
        else if (_regionMapTankPath is not null && _regionTerrainTankPath is not null
              && _playLogicTankPath is not null && _playObjectsTankPath is not null)
        {
            _loadDialog.Close();
            LaunchRegionForLoadWithTanks(_regionMapTankPath, _regionTerrainTankPath,
                _playLogicTankPath, _playObjectsTankPath, slot.Path);
        }
        else
        {
            _saveToastText = "Cannot load this save here.";
            _saveToastRemaining = SaveToastDuration;
        }
    }

    /// <summary>Write a named save from the Save Game window and raise the
    /// "Game 'X' saved successfully" banner. Unlike <see cref="DoQuickSave"/>
    /// (one fixed slot) this mints a timestamped file so many named saves
    /// coexist in the list.</summary>
    private void PerformNamedSave(string name)
    {
        var label = string.IsNullOrWhiteSpace(name)
            ? DateTime.Now.ToString("MMM d, yyyy") : name.Trim();
        var path = SiegeFX.Core.Save.SaveStore.NamedSavePath(label, DateTime.Now);
        try
        {
            var save = CaptureSave();
            save.DisplayName = label;
            SiegeFX.Core.Save.SaveStore.Save(path, save);
            Console.WriteLine($"  save: wrote '{label}' ({save.Actors.Count} actors) -> {path}");
            _saveToastText = $"Game '{label}' saved successfully.";
            _saveToastRemaining = SaveToastDuration;
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"  save: failed -- {ex.Message}");
            _saveToastText = "Save failed.";
            _saveToastRemaining = SaveToastDuration;
        }
    }

    /// <summary>Act on the Save Game window's button result. Save writes +
    /// closes + banners; Delete removes the highlighted file and refreshes the
    /// list in place; Cancel just closes.</summary>
    private void HandleSaveDialogResult(SaveGameDialog.Result r)
    {
        switch (r)
        {
            case SaveGameDialog.Result.Save:
                PerformNamedSave(_saveDialog.NameText);
                _saveDialog.Close();
                break;
            case SaveGameDialog.Result.Delete:
                if (_saveDialog.Selected is { } slot)
                {
                    SiegeFX.Core.Save.SaveStore.Delete(slot.Path);
                    // Re-open against the fresh list so the deleted row vanishes;
                    // keep whatever the player had typed in the name box.
                    _saveDialog.Open(SiegeFX.Core.Save.SaveStore.ListSaves(), _saveDialog.NameText);
                }
                break;
            case SaveGameDialog.Result.Cancel:
                _saveDialog.Close();
                break;
        }
    }

    // --- Adventurer's Handbook -------------------------------------------------

    /// <summary>Lazily load the ordered world tips off the play map tank the
    /// first time gameplay ticks in a region. One-shot even on failure (a map
    /// with no info/tips.gas simply never pops the handbook).</summary>
    private void LoadWorldTips()
    {
        _handbookTipsLoaded = true;
        if (_playMapTank is null || string.IsNullOrEmpty(_regionPath)) return;
        var tipsPath = SiegeFX.Core.Assets.WorldTips.TipsPathForRegion(_regionPath);
        if (tipsPath is null) return;
        try
        {
            var reader = new SiegeFX.Core.Tank.TankReader(_playMapTank);
            var tips = SiegeFX.Core.Assets.WorldTips.Load(reader, tipsPath);
            _handbook.SetTips(tips);
            _handbook.Disabled = _tipsDisabled;
            Console.WriteLine($"[handbook] loaded {tips.Count} tips from {tipsPath}");
        }
        catch (Exception ex) { Console.Error.WriteLine($"[handbook] load failed: {ex.Message}"); }
    }

    /// <summary>Auto-pop the next ordered tip as the player advances. The first
    /// tip greets the player a few seconds after they gain control; later tips
    /// pop after some travel or time, so they "come up as you play through the
    /// beginning" (DS1's own trigger cadence is engine-internal — this is the
    /// faithful clean-room stand-in). Stops once every tip has been seen or the
    /// player ticks "Disable tips".</summary>
    private void TickHandbookCadence(float dt)
    {
        if (!_handbookTipsLoaded) LoadWorldTips();
        if (_handbook.Count == 0 || _tipsDisabled) return;
        if (_nextTipIndex >= _handbook.Count) return;
        if (_player is null || _bootMode) return;
        // Only while the player actually has control of the world.
        if (_handbook.IsOpen || _saveDialog.IsOpen || _loadDialog.IsOpen || _pauseMenu.IsOpen || _optionsMenu.IsOpen
            || _creator.IsOpen || _dialogue.IsOpen || _vendor.IsOpen || _inventoryOpen
            || _questLogOpen) return;
        if (_nisPhase != NisPhase.Off) return;

        var pos = _player.CurrentTransform.Translation;
        if (!_tipTracking) { _tipLastPos = pos; _tipTracking = true; _tipTravel = 0f; _tipTimer = 0f; }
        var d = pos - _tipLastPos; d.Y = 0f;
        float step = d.Length();
        // Ignore teleport-scale jumps (zone transitions) so a warp doesn't
        // instant-fire the next tip.
        if (step < 15f) _tipTravel += step;
        _tipLastPos = pos;
        _tipTimer += dt;

        bool fire = _nextTipIndex == 0
            ? _tipTimer > 3f
            : (_tipTravel > 40f || _tipTimer > 60f);
        if (fire)
        {
            _handbook.OpenAuto(_nextTipIndex);
            Console.WriteLine($"[handbook] auto-pop tip {_nextTipIndex + 1}/{_handbook.Count}");
        }
    }

    /// <summary>F12 recall: open the handbook in browse mode (Prev/Next through
    /// the whole set) at the last-shown tip, or close it if already open.</summary>
    private void ToggleHandbook()
    {
        if (!_handbookTipsLoaded) LoadWorldTips();
        if (_handbook.Count == 0) return;
        if (_handbook.IsOpen) { OnHandbookClosed(); return; }
        int start = Math.Clamp((_nextTipIndex > 0 ? _nextTipIndex : 1) - 1, 0, _handbook.Count - 1);
        _handbook.OpenBrowse(start);
    }

    /// <summary>Escape / Resume path. Auto-pops advance the cadence to the next
    /// tip on dismissal; browse (F12) recalls don't.</summary>
    private void CloseHandbook() => OnHandbookClosed();

    private void OnHandbookClosed()
    {
        if (!_handbook.BrowseMode)
        {
            _nextTipIndex = Math.Min(_handbook.Count, _nextTipIndex + 1);
            _tipTravel = 0f; _tipTimer = 0f; _tipTracking = false;
        }
        _handbook.Close();
    }

    private void HandleHandbookResult(HandbookPanel.Result r)
    {
        switch (r)
        {
            case HandbookPanel.Result.Close:
                OnHandbookClosed();
                break;
            case HandbookPanel.Result.ToggledDisable:
                // The checkbox toggled; keep the panel open. Persist the flag
                // via the next CaptureSave (mirrored on the panel).
                _tipsDisabled = _handbook.Disabled;
                // SC-OPTIONS-GAME — the handbook's own "Disable tips"
                // checkbox and the Game tab's Tutorial Tips toggle are the
                // same setting; keep them in lockstep.
                _optionsMenu.Live.TutorialTips = !_tipsDisabled;
                Console.WriteLine($"[handbook] tips {(_tipsDisabled ? "disabled" : "enabled")}");
                break;
        }
    }

    /// <summary>Phase 19c — reload the quicksave slot. Shared by the F9 key and
    /// the in-game menu's LOAD GAME button. Drops a half-finished scroll drag
    /// first (post-load slot contents differ, so a stale source index would
    /// misplace the spell).</summary>
    private void DoQuickLoad()
    {
        if (_cursorScroll is not null) ClearScrollDrag();
        var path = SiegeFX.Core.Save.SaveStore.QuicksavePath();
        try
        {
            if (!File.Exists(path))
                Console.WriteLine($"  load: no quicksave at {path}");
            else
                ApplySave(SiegeFX.Core.Save.SaveStore.Load(path));
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"  load: failed -- {ex.Message}");
        }
    }
